		http.NotFound(w, nil) //nolint:staticcheck
	}))
	defer srv.Close()

	api := client.New(srv.URL, nil)
	defer api.Close()

	cmd := &RestoreCmd{
		Namespace: "test",
		Directory: t.TempDir(),
		Key:       "absent",
	}
	err := cmd.Run(context.Background(), api, &CLI{})
